import{_ as o,a0 as l,w as m,s as p,ao as r,I as e,x as n,a1 as t,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件 | LCTT x X-CMD","titleTemplate":false,"description":"RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件 | LCTT (RHCE) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件 | LCTT (RHCE) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients","title":"RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件","tag":"RHCE","desc":""},"relativePath":"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients.md","filePath":"[post].md"}'),d={name:"RHCE/Part 6 - Setting Up Samba and Configure FirewallD and SELinux to Allow File Sharing on Linux or Windows Clients.md"};function u(b,a,w,S,f,x){const i=l("Link");return m(),p("div",null,[a[30]||(a[30]=r(`<h1 id="rhce-系列-六-安装-samba-并配置-firewalld-和-selinux-让-linux-和-windows-共享文件" tabindex="-1">RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件 <a class="header-anchor" href="#rhce-系列-六-安装-samba-并配置-firewalld-和-selinux-让-linux-和-windows-共享文件" aria-label="Permalink to “RHCE 系列（六）：安装 Samba 并配置 Firewalld 和 SELinux 让 Linux 和 Windows 共享文件”">​</a></h1><p>由于计算机很少作为一个独立的系统工作，作为一个系统管理员或工程师，就应该知道如何在有多种类型的服务器之间搭设和维护网络。</p><p>在本篇以及该系列后面的文章中，我们会介绍用 Windows/Linux 配置 Samba 和 NFS 服务器以及 Linux 客户端。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/setup-samba-file-sharing-on-linux-windows-clients.png" alt="在 Linux 中配置 Samba 进行文件共享"></p><p><em>RHCE 系列第六部分 - 设置 Samba 文件共享</em></p><p>如果有人让你设置文件服务器用于协作或者配置很可能有多种不同类型操作系统和设备的企业环境，这篇文章就能派上用场。</p><p>由于你可以在网上找到很多关于 Samba 和 NFS 背景和技术方面的介绍，在这篇文章以及后续文章中我们就省略了这些部分直接进入到我们的主题。</p><h3 id="步骤一-安装-samba-服务器" tabindex="-1">步骤一： 安装 Samba 服务器 <a class="header-anchor" href="#步骤一-安装-samba-服务器" aria-label="Permalink to “步骤一： 安装 Samba 服务器”">​</a></h3><p>我们当前的测试环境包括两台 RHEL 7 和一台 Windows 8：</p><pre><code>1. Samba / NFS 服务器 [box1 (RHEL 7): 192.168.0.18], 
2. Samba 客户端 #1 [box2 (RHEL 7): 192.168.0.20]
3. Samba 客户端 #2 [Windows 8 machine: 192.168.0.106]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Testing-Setup-for-Samba.png" alt="测试安装 Samba"></p><p><em>测试安装 Samba</em></p><p>在 box1 中安装以下软件包：</p><pre><code># yum update &amp;&amp; yum install samba samba-client samba-common
</code></pre><p>在 box2：</p><pre><code># yum update &amp;&amp; yum install samba samba-client samba-common cifs-utils
</code></pre><p>安装完成后，就可以配置我们的共享了。</p><h3 id="步骤二-设置通过-samba-进行文件共享" tabindex="-1">步骤二： 设置通过 Samba 进行文件共享 <a class="header-anchor" href="#步骤二-设置通过-samba-进行文件共享" aria-label="Permalink to “步骤二： 设置通过 Samba 进行文件共享”">​</a></h3>`,18)),e("p",null,[a[1]||(a[1]=n("Samba 这么重要的原因之一是它为 SMB/CIFS 客户端（LCTT 译注：SMB 是微软和英特尔制定的一种通信协议，CIFS 是其中一个版本，更详细的介绍可以参考 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Server_Message_Block"},{default:s(()=>[...a[0]||(a[0]=[n("Wiki",-1)])]),_:1}),a[2]||(a[2]=n("）提供了文件和打印设备，这使得服务器在客户端看起来就是一个 Windows 系统（我必须承认写这篇文章的时候我有一点激动，因为这是我多年前作为一个新手 Linux 系统管理员的第一次设置）。",-1))]),a[31]||(a[31]=e("p",null,[e("strong",null,"添加系统用户并设置权限和属性")],-1)),e("p",null,[a[4]||(a[4]=n("为了允许组协作，我们会在 box1 中用 ",-1)),t(i,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:s(()=>[...a[3]||(a[3]=[n("useradd 命令",-1)])]),_:1}),a[5]||(a[5]=n("创建一个有两个用户（user1 和 user2）的组 finance 和目录 /finance。",-1))]),a[32]||(a[32]=e("p",null,"我们同时会把这个目录的组所有者更改为 finance 并把权限设置为 0777（所有者和组属主可读可写可执行）：",-1)),a[33]||(a[33]=e("pre",null,[e("code",null,`# groupadd finance
# useradd user1
# useradd user2
# usermod -a -G finance user1
# usermod -a -G finance user2
# mkdir /finance
# chmod 0770 /finance
# chgrp finance /finance
`)],-1)),a[34]||(a[34]=e("h3",{id:"步骤三-配置-selinux-和-firewalld",tabindex:"-1"},[n("步骤三： 配置 SELinux 和 Firewalld "),e("a",{class:"header-anchor",href:"#步骤三-配置-selinux-和-firewalld","aria-label":"Permalink to “步骤三： 配置 SELinux 和 Firewalld”"},"​")],-1)),a[35]||(a[35]=e("p",null,"在配置 /finance 作为 Samba 共享目录之前，我们需要像下面那样停用 SELinux 或设置恰当的布尔值和安全选项（否则，SELinux 会阻止客户端访问共享目录）：",-1)),a[36]||(a[36]=e("pre",null,[e("code",null,`# setsebool -P samba_export_all_ro=1 samba_export_all_rw=1
# getsebool –a | grep samba_export
# semanage fcontext –at samba_share_t "/finance(/.*)?"
# restorecon /finance
`)],-1)),e("p",null,[a[7]||(a[7]=n("另外我们必须确保 ",-1)),t(i,{href:"http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/"},{default:s(()=>[...a[6]||(a[6]=[n("firewalld",-1)])]),_:1}),a[8]||(a[8]=n(" 允许 Samba 流量通过。",-1))]),a[37]||(a[37]=r(`<pre><code># firewall-cmd --permanent --add-service=samba
# firewall-cmd --reload
</code></pre><h3 id="步骤四-配置-samba-共享目录" tabindex="-1">步骤四： 配置 Samba 共享目录 <a class="header-anchor" href="#步骤四-配置-samba-共享目录" aria-label="Permalink to “步骤四： 配置 Samba 共享目录”">​</a></h3><p>现在我们来看看配置文件 /etc/samba/smb.conf 并添加用于共享的章节（section）：我们希望组 finance 的成员可以浏览 /finance 的内容，在里面保存/创建文件或者子目录（默认权限为 0777，组所有者为 finance）：</p><p><strong>smb.conf</strong></p><hr><pre><code>[finance]
comment=Directory for collaboration of the company&#39;s finance team
browsable=yes
path=/finance
public=no
valid users=@finance
write list=@finance
writeable=yes
create mask=0770
Force create mode=0770
force group=finance
</code></pre><p>保存文件然后用 testparm 工具进行测试。如果这里有任何错误，命令的输出或提示你需要如何修复。否则，会显示你 Samba 服务器配置的回顾：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Test-Samba-Configuration.png" alt="测试 Samba 配置"></p><p><em>测试 Samba 配置</em></p><p>如果你要添加另一个公开的共享目录（意味着不需要任何验证），在 /etc/samba/smb.conf 中创建另一章节，在共享目录名称下面复制上面的章节，只需要把 public=no 更改为 public=yes 并去掉有效用户（valid users）和写列表（write list）命令。</p><h3 id="步骤五-添加-samba-用户" tabindex="-1">步骤五： 添加 Samba 用户 <a class="header-anchor" href="#步骤五-添加-samba-用户" aria-label="Permalink to “步骤五： 添加 Samba 用户”">​</a></h3><p>下一步，你需要添加 user1 和 user2 作为 Samba 的用户。要做到这点，你需要用 smbpasswd 命令，它会和 Samba 的数据库进行交互。会提示你输入一个命令用于你之后和共享目录连接：</p><pre><code># smbpasswd -a user1
# smbpasswd -a user2
</code></pre><p>最后，重启 Samda，并让系统启动时自动启动该服务，确保共享目录对网络客户端可用：</p><pre><code># systemctl start smb
# systemctl enable smb
# smbclient -L localhost –U user1
# smbclient -L localhost –U user2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Verify-Samba-Share.png" alt="验证 Samba 共享"></p><p><em>验证 Samba 共享</em></p><p>到这里，已经正确安装和配置了 Samba 文件服务器。现在让我们在 RHEL 7 和 Windows 8 客户端中测试该配置。</p><h3 id="步骤六-在-linux-中挂载-samba-共享" tabindex="-1">步骤六： 在 Linux 中挂载 Samba 共享 <a class="header-anchor" href="#步骤六-在-linux-中挂载-samba-共享" aria-label="Permalink to “步骤六： 在 Linux 中挂载 Samba 共享”">​</a></h3><p>首先，确保客户端可以访问 Samba 共享：</p><pre><code># smbclient –L 192.168.0.18 -U user2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Share-on-Linux.png" alt="在 Linux 上挂载 Samba 共享"></p><p><em>在 Linux 上挂载 Samba 共享</em></p><p>（为 user1 重复上面的命令）</p><p>正如任何其它存储介质，当你需要的时候你可以挂载（之后卸载）该网络共享：</p><pre><code># mount //192.168.0.18/finance /media/samba -o username=user1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Network-Share.png" alt="挂载 Samba 网络共享"></p><p><em>挂载 Samba 网络共享</em></p><p>（其中 /media/samba 是一个已有的目录）</p><p>或者在 /etc/fstab 文件中添加下面的条目以自动挂载：</p><p><strong>fstab</strong></p><hr><pre><code>//192.168.0.18/finance /media/samba cifs credentials=/media/samba/.smbcredentials,defaults 0 0
</code></pre><p>其中隐藏文件 /media/samba/.smbcredentials（它的权限被设置为 600 和 root:root）有两行内容，指示允许使用共享的账户的用户名和密码：</p><p><strong>.smbcredentials</strong></p><hr><pre><code>username=user1
password=PasswordForUser1
</code></pre><p>最后，让我们在 /finance 中创建一个文件并检查权限和属性：</p><pre><code># touch /media/samba/FileCreatedInRHELClient.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Create-File-in-Samba-Share.png" alt="在 Samba 共享中创建文件"></p><p><em>在 Samba 共享中创建文件</em></p><p>正如你看到的，用权限 0770 和属主 user1:finance 创建了文件。</p><h3 id="步骤七-在-windows-上挂载-samba-共享" tabindex="-1">步骤七： 在 Windows 上挂载 Samba 共享 <a class="header-anchor" href="#步骤七-在-windows-上挂载-samba-共享" aria-label="Permalink to “步骤七： 在 Windows 上挂载 Samba 共享”">​</a></h3><p>要在 Windows 上挂载 Samba 共享，进入 ‘我的计算机’ 并选择 ‘计算机’，‘网络驱动映射’。下一步，为要映射的驱动分配一个驱动器盘符并用不同的认证身份检查是否可以连接（下面的截图使用我的母语西班牙语）：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Mount-Samba-Share-in-Windows.png" alt="在 Windows 中挂载 Samba 共享"></p><p><em>在 Windows 中挂载 Samba 共享</em></p><p>最后，让我们新建一个文件并检查权限和属性：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/09/Create-Files-on-Windows-Samba-Share.png" alt="在 Windows Samba 共享中新建文件"></p><p>在 Windows Samba 共享中新建文件</p><pre><code># ls -l /finance
</code></pre><p>这次文件属于 user2，因为这是我们用于从 Windows 客户端中连接的账户。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,52)),e("p",null,[a[11]||(a[11]=n("在这篇文章中我们不仅介绍了如何使用不同操作系统设置 Samba 服务器和两个客户端，也介绍了",-1)),t(i,{href:"http://www.tecmint.com/configure-firewalld-in-centos-7/"},{default:s(()=>[...a[9]||(a[9]=[n("如何配置 Firewalld",-1)])]),_:1}),a[12]||(a[12]=n(" 和 ",-1)),t(i,{href:"http://www.tecmint.com/selinux-essentials-and-control-filesystem-access/"},{default:s(()=>[...a[10]||(a[10]=[n("服务器中的 SELinux",-1)])]),_:1}),a[13]||(a[13]=n(" 以获取所需的组协作功能。",-1))]),e("p",null,[a[15]||(a[15]=n("最后，同样重要的是，我推荐阅读网上的 ",-1)),t(i,{href:"https://www.samba.org/samba/docs/man/manpages-3/smb.conf.5.html"},{default:s(()=>[...a[14]||(a[14]=[n("smb.conf man 手册",-1)])]),_:1}),a[16]||(a[16]=n(" ，查看其它比本文中介绍的场景更加合适你的场景的配置命令。",-1))]),a[38]||(a[38]=e("p",null,"正如往常，欢迎在下面的评论框中留下你的评论或建议。",-1)),a[39]||(a[39]=e("hr",null,null,-1)),e("p",null,[a[18]||(a[18]=n("via: ",-1)),t(i,{href:"http://www.tecmint.com/setup-samba-file-sharing-for-linux-windows-clients/"},{default:s(()=>[...a[17]||(a[17]=[n("http://www.tecmint.com/setup-samba-file-sharing-for-linux-windows-clients/",-1)])]),_:1})]),e("p",null,[a[22]||(a[22]=n("作者：",-1)),t(i,{href:"http://www.tecmint.com/author/gacanepa/"},{default:s(()=>[...a[19]||(a[19]=[n("Gabriel Cánepa",-1)])]),_:1}),a[23]||(a[23]=n(" 译者：",-1)),t(i,{href:"http://www.mutouxiaogui.cn/blog/"},{default:s(()=>[...a[20]||(a[20]=[n("ictlyh",-1)])]),_:1}),a[24]||(a[24]=n(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:s(()=>[...a[21]||(a[21]=[n("wxy",-1)])]),_:1})]),e("p",null,[a[27]||(a[27]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[25]||(a[25]=[n("LCTT",-1)])]),_:1}),a[28]||(a[28]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:s(()=>[...a[26]||(a[26]=[n("Linux中国",-1)])]),_:1}),a[29]||(a[29]=n(" 荣誉推出",-1))])])}const C=o(d,[["render",u]]);export{L as __pageData,C as default};
